export type CurveResampleParams = {
  /** Points per spline. */
  count?: number | null;
  /** Name of a new curve object for the result; edits the target in place when omitted. */
  output?: string | null;
  /** Segments per curved Bezier span before resampling. */
  resolution?: number;
  /** Distance between points instead of a count (rounded so the spacing is even). */
  spacing?: Length | null;
  /** Curve object (name, path or id). */
  target: string;
};

/** `curve.offset`: Moves each spline sideways by a distance within its plane, with mitered or beveled corners. */
export type CurveOffsetParams = {
  /**
   * Outward for closed splines, to the left (seen from the normal) for
   * open ones; negative goes the other way.
   */
  distance: Length;
  /** Convex corners whose miter would exceed this many distances are beveled. */
  miter_limit?: number;
  /**
   * Offsets within planes perpendicular to this direction; the curve's
   * own plane when omitted (+Y for straight lines).
   */
  normal?: [number, number, number] | null;
  /** Name of a new curve object for the result; edits the target in place when omitted. */
  output?: string | null;
  /** Segments per curved Bezier span before offsetting. */
  resolution?: number;
  /** Curve object (name, path or id). */
  target: string;
};

/** `curve.fillet`: Rounds every corner of each spline with a tangent arc, or chamfers it with one segment. */
export type CurveFilletParams = {
  /** Name of a new curve object for the result; edits the target in place when omitted. */
  output?: string | null;
  /** Arc radius at each corner (shrunk where the segments are too short). */
  radius: Length;
  /** Segments per curved Bezier span before filleting. */
  resolution?: number;
  /** Segments per arc; 1 cuts a chamfer. */
  segments?: number;
  /** Curve object (name, path or id). */
  target: string;
};

/** `gen.lathe`: Revolves a profile around an axis into a round object with groups side, cap_top, cap_bottom and profile_<i>. */
export type GenLatheParams = {
  /** Revolution (degrees); partial turns start at the front and stay open. */
  angle?: Angle;
  /** Axis to revolve around; the profile's height runs along it. */
  axis?: AxisParam;
  /** How the open ends of a full turn are filled. */
  cap?: CapParam;
  /** Joins the last point back to the first (rings such as tires and washers; points only). */
  closed?: boolean;
  /** Height of a preset profile (presets only). */
  height?: Length | null;
  /** Object name; a free name such as `lathe_1` is picked when omitted. */
  name?: string | null;
  /** Parent object (name, path or id); top level when omitted. */
  parent?: string | null;
  /**
   * Origin position in the parent's space. Built from a curve object, the result takes the curve's place
   * (parent and transform) unless `parent` or `position` is given.
   */
  position?: [Length, Length, Length] | null;
  /** The profile to revolve. */
  profile: Profile;
  /** Largest radius of a preset profile (presets only). */
  radius?: Length | null;
  /** Segments per curved span of a smooth profile. */
  resolution?: number;
  /** Segments around the axis; adapts to the size and asset class when omitted. */
  segments?: number | null;
  /** A smooth Bezier through the points instead of straight segments (points and polyline curves). */
  smooth?: boolean;
};

/** `gen.extrude_shape`: Turns a flat outline with holes into a solid of a given depth, with optional round or chamfered rims. */
export type GenExtrudeShapeParams = {
  /** Rounded or chamfered rims; sharp when omitted. */
  bevel?: ShapeBevel | null;
  /** A curve object of closed splines instead of `outline` (inner splines become holes); its plane is used. */
  curve?: string | null;
  /** Thickness along the plane's normal (the back stays on the plane). */
  depth?: Length;
  /** Holes inside the outline, as point lists like the outline. */
  holes?: [Length, Length][][];
  /** Object name; a free name such as `shape_1` is picked when omitted. */
  name?: string | null;
  /** Outline points `[x, y]` in the shape plane (closed automatically, either winding). */
  outline?: [Length, Length][] | null;
  /** Parent object (name, path or id); top level when omitted. */
  parent?: string | null;
  /** Plane of `outline` points; the shape extrudes along its normal (+Z, +Y, +X). */
  plane?: PlaneParam;
  /**
   * Origin position in the parent's space. Built from a curve object, the result takes the curve's place
   * (parent and transform) unless `parent` or `position` is given.
   */
  position?: [Length, Length, Length] | null;
  /** Segments per curved span of Bezier splines. */
  resolution?: number;
};

/** `gen.sweep`: Carries a cross section along a path into rails, trims, frames, handles and cables, with twist and taper. */
export type GenSweepParams = {
  /** Fills the ends of a closed cross section on an open path. */
  caps?: boolean;
  /** Object name; a free name such as `sweep_1` is picked when omitted. */
  name?: string | null;
  /** Parent object (name, path or id); top level when omitted. */
  parent?: string | null;
  /** The path the cross section follows. */
  path: Path;
  /** Joins the last inline path point back to the first. */
  path_closed?: boolean;
  /**
   * Origin position in the parent's space. Built from a path curve, the result takes the curve's place
   * (parent and transform) unless `parent` or `position` is given.
   */
  position?: [Length, Length, Length] | null;
  /** The cross section. */
  profile: Section;
  /** Whether inline profile points close into a loop (open profiles make trims and ribbons). */
  profile_closed?: boolean;
  /** Segments per curved span of Bezier curves. */
  resolution?: number;
  /** Cross section scale at the start and the end (taper). */
  scale?: [number, number];
  /** Points around a circle cross section; adapts to its size when omitted. */
  segments?: number | null;
  /** A smooth Bezier through inline path points instead of straight segments. */
  smooth_path?: boolean;
  /** Turn of the cross section from start to end (degrees); closed paths need whole turns. */
  twist?: Angle;
  /** Direction the cross section's y leans toward at the start. */
  up?: [number, number, number] | null;
};

/** `gen.pipe`: Builds a round pipe along a path with smooth bends at the corners and quad caps. */
export type GenPipeParams = {
  /** Radius of the bends at path corners (twice the pipe radius when omitted; 0 for mitered joints). */
  bend_radius?: Length | null;
  /** Segments per bend. */
  bend_segments?: number;
  /** Closes the ends of an open pipe. */
  caps?: boolean;
  /** Object name; a free name such as `pipe_1` is picked when omitted. */
  name?: string | null;
  /** Parent object (name, path or id); top level when omitted. */
  parent?: string | null;
  /** The path the pipe follows. */
  path: Path;
  /** Joins the last inline path point back to the first (rings). */
  path_closed?: boolean;
  /**
   * Origin position in the parent's space. Built from a path curve, the result takes the curve's place
   * (parent and transform) unless `parent` or `position` is given.
   */
  position?: [Length, Length, Length] | null;
  /** Pipe radius. */
  radius?: Length;
  /** Segments per curved span of Bezier curves. */
  resolution?: number;
  /** Points around the pipe; adapts to its size when omitted (a multiple of 4 gives quad caps). */
  segments?: number | null;
  /** A smooth Bezier through inline path points instead of straight runs with bends. */
  smooth_path?: boolean;
};

/** `gen.loft`: Builds a surface through a sequence of cross sections, resampling them so their point counts match. */
export type GenLoftParams = {
  /** Fills the first and last closed sections. */
  caps?: boolean;
  /** Joins the last section back to the first (rings). */
  closed?: boolean;
  /** Object name; a free name such as `loft_1` is picked when omitted. */
  name?: string | null;
  /** Parent object (name, path or id); top level when omitted. */
  parent?: string | null;
  /** Points per section after even resampling; sections keep their points when their counts already match. */
  points?: number | null;
  /**
   * Origin position in the parent's space. With curve sections, the result takes the first curve's place
   * (parent and transform) unless `parent` or `position` is given; other curves keep their world places.
   */
  position?: [Length, Length, Length] | null;
  /** Segments per curved span of Bezier curves. */
  resolution?: number;
  /** Cross sections in order: point lists `[x, y, z]` or `{"curve": name}`. */
  sections: Path[];
  /** Whether inline point sections are closed loops (curves carry their own flag). */
  sections_closed?: boolean;
  /** Curves through the sections instead of straight bands (use with steps > 1). */
  smooth?: boolean;
  /** Rows from one section to the next. */
  steps?: number;
};

/** `prim.plane`: Creates a flat grid of quads in the XZ plane facing up (+Y). */
export type PrimPlaneParams = {
  /** Rarely needed settings. */
  advanced?: PlaneAdvanced;
  /** Size along Z. */
  depth?: Length;
  /** Object name; a free name such as `plane_1` is picked when omitted. */
  name?: string | null;
  /** Parent object (name, path or id); top level when omitted. */
  parent?: string | null;
  /** Center position in the parent's space. */
  position?: [Length, Length, Length];
  /** Size along X. */
  width?: Length;
};

/** `select.save`: Stores the elements a selector picks as a named group on the mesh. */
export type SelectSaveParams = {
  /** Group name; an existing group of that name is replaced. */
  name: string;
  /** Elements to store. */
  select: Selector;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `select.grow`: Adds the neighbouring rings of elements to a group (faces across edges, edges and vertices through vertices). */
export type SelectGrowParams = {
  /** Group to grow or shrink. */
  group: string;
  /** Store the result under this name instead of changing the group. */
  save_as?: string | null;
  /** Rings of neighbours to add or remove. */
  steps?: number;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `select.shrink`: Removes the outermost rings of elements from a group. */
export type SelectShrinkParams = {
  /** Group to grow or shrink. */
  group: string;
  /** Store the result under this name instead of changing the group. */
  save_as?: string | null;
  /** Rings of neighbours to add or remove. */
  steps?: number;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `select.group_delete`: Removes a named group; the geometry stays. */
export type SelectGroupDeleteParams = {
  /** Group to remove (the geometry stays). */
  group: string;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `select.group_rename`: Renames a named group, keeping its elements and position in the list. */
export type SelectGroupRenameParams = {
  /** Current group name. */
  from: string;
  /** Mesh object (name, path or id). */
  target: string;
  /** New group name; must be free. */
  to: string;
};

/** `edit.extrude`: Pulls faces out along their normals (or a direction) and joins them to the surface with side walls. */
export type EditExtrudeParams = {
  /** Move along this object-space direction instead of the face normals. */
  direction?: [number, number, number] | null;
  /** How far the faces move; negative pushes them in. */
  distance?: Length;
  /** `region` (default) or `individual`. */
  mode?: ExtrudeModeParam;
  /** Faces to extrude. */
  select: Selector;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `edit.inset`: Shrinks faces inward within their surface, leaving a rim of quads, and optionally pushes the inner part in or out. */
export type EditInsetParams = {
  /** Moves the inner faces along their normals; negative makes a recess. */
  depth?: Length;
  /** `region` (default) or `individual`. */
  mode?: InsetModeParam;
  /** Faces to inset. */
  select: Selector;
  /** Mesh object (name, path or id). */
  target: string;
  /** Width of the rim, measured inside the faces. */
  thickness?: Length;
};

/** `edit.poke`: Splits each face into a fan of triangles around a new center vertex, optionally raised into a pyramid. */
export type EditPokeParams = {
  /** Moves each new center vertex along its face normal (a pyramid when positive). */
  offset?: Length;
  /** Faces to poke; every face when omitted. */
  select?: Selector | null;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `edit.triangulate`: Splits quads and n-gons into triangles with the diagonals that keep angles largest (beauty), adding no vertices. */
export type EditTriangulateParams = {
  /** Faces to triangulate; every face when omitted. */
  select?: Selector | null;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `edit.tris_to_quads`: Joins pairs of adjacent triangles into quads, best-shaped pairs first, where the result is flat and square enough. */
export type EditTrisToQuadsParams = {
  /** Rarely needed settings. */
  advanced?: TrisToQuadsAdvanced;
  /** Largest angle between the two triangles (degrees); larger folds stay triangles. */
  max_face_angle?: Angle;
  /** Largest difference of a quad corner from a right angle (degrees). */
  max_shape_angle?: Angle;
  /** Triangles to join; every face when omitted (other faces are skipped). */
  select?: Selector | null;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `edit.split`: Detaches faces from the rest of the mesh by duplicating the vertices along the border, leaving them in place. */
export type EditSplitParams = {
  /** Faces to detach from the rest of the mesh. */
  select: Selector;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `edit.flip`: Reverses the facing of every connected part that contains a selected face. */
export type EditFlipParams = {
  /** Faces whose connected parts are flipped; every part when omitted. */
  select?: Selector | null;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `edit.subdivide`: Splits faces into quads at edge and face middles without moving anything (flat subdivision). */
export type EditSubdivideParams = {
  /** Times to split (1 to 6); each level makes about 4 times as many faces. */
  levels?: number;
  /** Faces to subdivide; every face when omitted. */
  select?: Selector | null;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `edit.loop_cut`: Cuts new edge loops across the ring of quads that runs through the selected edges. */
export type EditLoopCutParams = {
  /** Parallel loops per ring (1 to 64). */
  cuts?: number;
  /** Slides a single cut toward either side, from -1 to 1 (0 is the middle). */
  offset?: number;
  /**
   * Edges that the cut crosses: each picks the ring of quads running
   * across it (several edges of one ring cut it once).
   */
  select: Selector;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `edit.bridge`: Joins two holes (boundary loops) with a band of quads. */
export type EditBridgeParams = {
  /** Rings of quads along the bridge (1 to 64). */
  segments?: number;
  /**
   * Boundary edges (or vertices, or faces next to them) of exactly two
   * holes; when omitted the mesh must have exactly two holes.
   */
  select?: Selector | null;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `edit.merge`: Merges selected vertices into one point (center) or each connected run into its own point (collapse). */
export type EditMergeParams = {
  /** `center` (default) or `collapse`. */
  mode?: MergeModeParam;
  /** Vertices to merge (edges and faces select their vertices). */
  select: Selector;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `edit.merge_by_distance`: Welds vertices that lie closer together than a distance, closing seams between joined or mirrored parts. */
export type EditMergeByDistanceParams = {
  /** Vertices closer than this weld together. */
  distance?: Length;
  /** Vertices that may weld (edges and faces select their vertices); all when omitted. */
  select?: Selector | null;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `edit.dissolve`: Removes vertices, edges or faces while keeping the surface closed, merging the faces around them into polygons. */
export type EditDissolveParams = {
  /** For `limited`: faces meeting flatter than this merge (degrees). */
  angle?: Angle;
  /** `auto` (by the selector's element kind) or `limited`. */
  mode?: DissolveModeParam;
  /**
   * Vertices, edges or faces to dissolve; for `limited`, the faces to
   * simplify (all when omitted).
   */
  select?: Selector | null;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `edit.plane_cut`: Cuts the mesh along a plane, optionally removing one side and capping the opening. */
export type EditPlaneCutParams = {
  /** Close the holes the cut leaves on the plane (when one side is removed). */
  fill?: boolean;
  /** `both` (default), `above` (the side the normal points to) or `below`. */
  keep?: KeepParam;
  /** Plane normal in object space; [0, 1, 0] cuts horizontally. */
  normal?: [number, number, number];
  /** A point on the plane, in object space. */
  point?: [Length, Length, Length];
  /** Cut only these faces (a knife cut); neighbours gain the crossing points. All faces when omitted. */
  select?: Selector | null;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `edit.symmetrize`: Makes a mesh mirror-symmetric: keeps one half and replaces the other with its mirror image, welded at the seam. */
export type EditSymmetrizeParams = {
  /** Mirror across the plane through the origin normal to this axis. */
  axis?: AxisParam;
  /** Keep the positive half (default) and mirror it onto the negative one; false does the opposite. */
  keep_positive?: boolean;
  /** Mesh object (name, path or id). */
  target: string;
  /** Vertices this close to the plane weld into the seam. */
  weld?: Length;
};

/** `edit.thicken`: Gives surfaces a wall thickness: an offset back side joined to the front along open borders. */
export type EditThickenParams = {
  /** Where the wall goes: -1 behind the surface (default), 0 centered, 1 in front. */
  offset?: number;
  /** Whole surfaces to thicken; every face when omitted. */
  select?: Selector | null;
  /** Mesh object (name, path or id). */
  target: string;
  /** Wall thickness. */
  thickness?: Length;
};

/** `edit.smooth`: Smooths vertex positions without shrinking the shape (Taubin smoothing). */
export type EditSmoothParams = {
  /** Rarely needed settings. */
  advanced?: SmoothAdvanced;
  /** Strength per round, 0 to 1. */
  factor?: number;
  /** Rounds of smoothing (1 to 1000). */
  iterations?: number;
  /** Vertices to smooth (edges and faces select their vertices); all when omitted. */
  select?: Selector | null;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `edit.bevel`: Rounds or chamfers edges: each edge becomes a strip of faces `width` wide, with caps where strips meet or end. */
export type EditBevelParams = {
  /** Rarely needed settings. */
  advanced?: BevelAdvanced;
  /** Profile for 2 or more segments: 0.5 round, toward 0 flat, toward 1 pointed. */
  profile?: number;
  /** Faces across the bevel: 1 is a flat chamfer, 2 or more round it. */
  segments?: number;
  /** Edges to bevel (faces select their edges); for example {"edges": {"sharp": true}}. */
  select: Selector;
  /** Mesh object (name, path or id). */
  target: string;
  /** Distance from each edge to the new edges, measured inside the faces. */
  width?: Length;
};

/** `edit.transform`: Moves, rotates and scales selected vertices, edges or faces of a mesh, optionally with proportional editing. */
export type EditTransformParams = {
  /** Orientation axes in object space as three columns (X, Y, Z); the object's own axes when omitted. */
  axes?: [[number, number, number], [number, number, number], [number, number, number]] | null;
  /** `median` (default), `bounds_center`, `individual` or `point`. */
  pivot?: PivotParam;
  /** Pivot for `pivot: "point"`, in object space. */
  pivot_point?: [Length, Length, Length];
  /** Proportional editing: nearby unselected vertices follow with a falloff. */
  proportional?: ProportionalParams | null;
  /** Rotation around the orientation axes (degrees, applied X, then Y, then Z). */
  rotate?: [Angle, Angle, Angle];
  /** Scale along the orientation axes (1 changes nothing, 0 flattens). */
  scale?: [number, number, number];
  /** Vertices to transform (edges and faces select their vertices). */
  select: Selector;
  /** Mesh object (name, path or id). */
  target: string;
  /** Offset along the orientation axes. */
  translate?: [Length, Length, Length];
};

/** `edit.shrink_fatten`: Moves vertices along their normals: positive fattens (outward), negative shrinks. */
export type EditShrinkFattenParams = {
  /** Offset along the normals; negative shrinks. */
  distance?: Length;
  /** Stretch the offset at creases so faces move by the full distance. */
  even?: boolean;
  /** Vertices to move (edges and faces select their vertices). */
  select: Selector;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `edit.edge_slide`: Slides edges (an edge loop) along the surface toward the neighbouring edges on one side. */
export type EditEdgeSlideParams = {
  /** How far, from -1 to 1: 1 reaches the neighbouring vertices on one side, -1 the other side. */
  factor?: number;
  /** Edges to slide (typically an edge loop). */
  select: Selector;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `edit.fill`: Closes holes (loops of boundary edges) with one face each. */
export type EditFillParams = {
  /**
   * Holes to fill: those with a selected boundary edge or vertex, or
   * bordering a selected face. Every hole when omitted.
   */
  select?: Selector | null;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `edit.recalc_normals`: Makes every connected part of a mesh face outward (or inward), flipping parts that face the wrong way. */
export type EditRecalcNormalsParams = {
  /** Point normals inward instead (for interiors seen from inside, such as rooms). */
  inside?: boolean;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `edit.delete_elements`: Deletes the selected faces (or every face using the selected edges or vertices) and anything left unused. */
export type EditDeleteElementsParams = {
  /**
   * Faces to delete. Selecting edges or vertices deletes every face that
   * uses them.
   */
  select: Selector;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `shade.smooth_by_angle`: Shades smoothly across gentle edges and keeps edges sharper than an angle hard. */
export type ShadeSmoothByAngleParams = {
  /** Edges whose faces meet at more than this many degrees become sharp. */
  angle?: Angle;
  /** Keep edges that are sharp already (marked by hand or by primitives). */
  keep_sharp?: boolean;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `shade.mark_sharp`: Marks edges sharp: shading breaks there (hard edges). */
export type ShadeMarkSharpParams = {
  /** Edges (faces select their edges, vertices the edges between them); every edge when omitted. */
  select?: Selector | null;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `shade.clear_sharp`: Clears the sharp mark from edges so shading flows smoothly across them. */
export type ShadeClearSharpParams = {
  /** Edges (faces select their edges, vertices the edges between them); every edge when omitted. */
  select?: Selector | null;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `shade.set_flat`: Shades faces flat (faceted) by marking all their edges sharp. */
export type ShadeSetFlatParams = {
  /** Faces to shade; every face when omitted. */
  select?: Selector | null;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `shade.set_smooth`: Shades faces smoothly by clearing the sharp mark on the edges between them. */
export type ShadeSetSmoothParams = {
  /** Faces to shade; every face when omitted. */
  select?: Selector | null;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `shade.weighted_normals`: Sets custom normals weighted by face area so large flat faces stay flat-shaded next to small bevel faces. */
export type ShadeWeightedNormalsParams = {
  /** Mesh object (name, path or id). */
  target: string;
  /** `area` (default), `angle` or `area_angle`. */
  weighting?: WeightingParam;
};

/** `shade.crease`: Sets how sharp edges stay under `subd.catmull_clark`: 0 rounds them, 1 keeps them sharp. */
export type ShadeCreaseParams = {
  /** Edges to crease (faces select their edges, vertices the edges between them). */
  select: Selector;
  /** Mesh object (name, path or id). */
  target: string;
  /** Crease weight from 0 (smooth) to 1 (stays sharp under subdivision). */
  weight?: number;
};

/** `subd.catmull_clark`: Smooths the whole mesh by Catmull-Clark subdivision, keeping creased edges sharp. */
export type SubdCatmullClarkParams = {
  /** Rarely needed settings. */
  advanced?: SubdAdvanced;
  /** Subdivision levels (1 to 6); each makes about 4 times as many faces. */
  levels?: number;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `deform.bend`: Curls a shape along an axis onto a circular arc, turning by an angle over its length. */
export type DeformBendParams = {
  /** Total turn over the whole length (degrees). */
  angle?: Angle;
  /** The axis the shape runs along (it curls from its low end). */
  axis?: AxisParam;
  /** Vertices to bend (edges and faces select theirs); all when omitted. */
  select?: Selector | null;
  /** Mesh object (name, path or id). */
  target: string;
  /** The axis it bends toward (positive side; a negative angle bends the other way). */
  toward?: AxisParam;
};

/** `deform.twist`: Twists a shape around an axis, from no turn at its low end to `angle` at its high end. */
export type DeformTwistParams = {
  /** Turn at the far end (degrees; the low end stays). */
  angle?: Angle;
  /** Axis to twist around (through the object origin). */
  axis?: AxisParam;
  /** Vertices to twist (edges and faces select theirs); all when omitted. */
  select?: Selector | null;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `deform.taper`: Scales a shape toward its axis progressively, from full size at its low end to `factor` at its high end. */
export type DeformTaperParams = {
  /** Axis the taper runs along (scaling toward the axis line through the origin). */
  axis?: AxisParam;
  /** Scale at the far end (0 makes a point, 1 changes nothing, 2 doubles). */
  factor?: number;
  /** Vertices to taper (edges and faces select theirs); all when omitted. */
  select?: Selector | null;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `deform.displace`: Moves vertices along their normals by seeded fractal noise (bumps, rocks, terrain, organic variation). */
export type DeformDisplaceParams = {
  /** Noise layers (1 to 8): more adds finer detail. */
  octaves?: number;
  /** Size of the bumps. */
  scale?: Length;
  /** Noise seed: the same seed gives the same shape. The call's seed when omitted. */
  seed?: number | null;
  /** Vertices to displace (edges and faces select theirs); all when omitted. */
  select?: Selector | null;
  /** Largest offset along the normals. */
  strength?: Length;
  /** Mesh object (name, path or id). */
  target: string;
};

/** `expect.add`: Adds a test for the model (size, symmetry, attachment, no intersections, budget, watertight) that runs after every change. */
export type ExpectAddParams = {
  /** The test: one of dims, symmetric, attached, not_intersecting, budget, watertight. */
  expect: ExpectArgs;
  /** Name; `E1`, `E2`, ... when omitted. */
  name?: string | null;
};

/** `expect.remove`: Removes an expectation by name. */
export type ExpectRemoveParams = {
  /** Name of the expectation, for example `E2`. */
  name: string;
};

